python3 << 'EOF'
import re,glob,os,subprocess
live=set()
for line in open('ROADMAP.md'):
    if line.startswith('|'):
        c=line.strip().strip('|').split('|')
        if c and c[0].strip().isdigit(): live.add(int(c[0].strip()))
arch=set()
for f in glob.glob('docs/queue-archive/rotated-*.md'):
    arch|=set(int(x) for x in re.findall(r'^\|\s*(\d+)\s*\|',open(f).read(),re.M))
print('live rows:',len(live),'archived rows:',len(arch),'overlap:',sorted(live&arch))
allids=live|arch
missing=[n for n in range(1,max(allids)+1) if n not in allids]
print('ids in neither live nor archive:',len(missing), missing[:40],'...' if len(missing)>40 else '')
# citations
files=subprocess.check_output(['git','ls-files']).decode().split()
pat=re.compile(r'(?:ROADMAP(?:\.md)?\s+rows?|queue rows?|ROADMAP rows?|roadmap rows?)\s+(\d+)')
cites={}
for f in files:
    if not f.endswith(('.md','.py','.sh','.json')): continue
    if f.startswith('docs/queue-archive/') or f=='ROADMAP.md' or f=='JOURNAL.md': continue
    try: t=open(f,errors='ignore').read()
    except: continue
    for m in pat.finditer(t):
        n=int(m.group(1))
        cites.setdefault(n,set()).add(f)
rot=[(n,sorted(v)) for n,v in sorted(cites.items()) if n in arch]
print('\ncitations pointing at ROTATED rows:',len(rot))
for n,v in rot: print(' row',n,'→',v[:6])
dead=[(n,sorted(v)) for n,v in sorted(cites.items()) if n not in allids]
print('\ncitations pointing at NONEXISTENT rows:',len(dead))
for n,v in dead[:20]: print(' row',n,'→',v[:5])
EOF

